// Office-Dateien (Word, Excel, PowerPoint): Vorschau direkt im Browser (24. 11. 2026).
// Die Bibliotheken liegen am eigenen Server in /vorschau und laden erst beim Öffnen einer Vorschau;
// die Datei geht an keinen fremden Dienst.
const OFFICE = /\.(docx|docm|dotx|xlsx|xlsm|xls|ods|pptx|pptm|ppsx)$/i;
let officeLaden = null;
function officeModul() {
  return officeLaden || (officeLaden = new Promise((ok, nein) => {
    const s = document.createElement("script");
    s.src = "vorschau/office-vorschau.js?v=1";
    s.onload = () => (window.MateVorschau ? ok(window.MateVorschau) : nein(new Error("MateVorschau fehlt")));
    s.onerror = () => { officeLaden = null; s.remove(); nein(new Error("vorschau/office-vorschau.js nicht ladbar")); };
    document.head.appendChild(s);
  }));
}
async function officeVorschau(box, f) {
  box.innerHTML = '<div class="mv-info" style="padding:24px 16px;text-align:center;color:var(--muted)">Vorschau wird geladen …</div>';
  try {
    const [mv, daten] = await Promise.all([
      officeModul(),
      fetch(f.url, { credentials: "same-origin" }).then((r) => { if (!r.ok) throw new Error("HTTP " + r.status); return r.arrayBuffer(); }),
    ]);
    if (box.isConnected) await mv.zeigen(box, daten, f.n);
  } catch (x) {
    console.warn("Office-Vorschau:", x);
    const i = box.querySelector(".mv-info");
    if (i) i.textContent = "Für diese Datei klappt die Vorschau leider nicht. Lade sie herunter, um sie zu öffnen.";
  }
}

